effect.shader:
const vec3 gmLuma = vec3(0.2126, 0.7152, 0.0722);
float gmDepth(vec2 uv) {
vec4 d = texture2DCv(comp.texture, clamp(uv, 0.0, 1.0));
float value = dot(d.rgb, gmLuma);
return invertDepth ? 1.0 - value : value;
}
void main() {
vec2 uv = acScreenNorm;
vec2 texSize = max(inputImg.size, vec2(1.0));
vec4 src = texture2DCv(inputImg.texture, uv);
float centerDepth = gmDepth(uv);
float depthDistance = abs(centerDepth - focusDepth);
float coc = smoothstep(focusRange, 1.0, depthDistance);
float radiusPx = maxBlurPx * coc;
const mat2 goldenTurn = mat2(-0.7373689, -0.6754903, 0.6754903, -0.7373689);
vec2 direction = vec2(1.0, 0.0);
vec4 sum = src;
float weightSum = 1.0;
for (int i = 0; i < 20; i++) {
float radial = sqrt((float(i) + 0.5) / 20.0);
vec2 offset = direction * radial * radiusPx / texSize;
vec2 sampleUv = clamp(uv + offset, 0.0, 1.0);
float sampleDepth = gmDepth(sampleUv);
float depthWeight = exp(-abs(sampleDepth - centerDepth) * edgeProtection);
vec4 sampleColor = texture2DCv(inputImg.texture, sampleUv);
float highlight = max(dot(sampleColor.rgb, gmLuma) - 0.65, 0.0);
sampleColor.rgb *= 1.0 + highlight * highlightBoost;
sum += sampleColor * depthWeight;
weightSum += depthWeight;
direction = goldenTurn * direction;
}
vec4 blurred = sum / max(weightSum, 0.0001);
gl_FragColor = mix(src, blurred, clamp(mixAmount, 0.0, 1.0));
}
